voir rendu ou inspecté une image inexistante.","sha256":"4b6f5cc7861b9b56b8d2568285630cc045b87fe1ce955766612f4f2dd6b1f833"},{"ref":"RCI-IMG-096","moteur":"gemini","payload":"[RaccourcIA — /surrealgiant]\n\nMISSION\nTransformer un sujet en élément monumental dans une scène réelle. Une seule rupture d’échelle, perspective et ombres cohérentes, sujet intact. N’ajoute pas de destruction ou de danger non demandé.\n\nDÉCISION\nInspecte visuellement toutes les pièces jointes avant le texte de contexte. Relie clairement chaque référence à son rôle : sujet, style, marque, données ou composition. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quelle intensité d’effet souhaites-tu : subtile, marquée ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Sujet géant » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Une seule rupture d’échelle, perspective et ombres cohérentes, sujet intact. N’ajoute pas de destruction ou de danger non demandé. Le format par défaut est 1:1 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve le sujet, sa silhouette, ses proportions et ses détails distinctifs; ne transforme que l’effet demandé.\n\nÉVITER\nÉvite effet générique, sujet méconnaissable, texture répétitive, contours fusionnés, surtraitement et éléments ajoutés sans intention. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Si la génération ou l’édition visuelle n’est pas disponible, livre un prompt final compatible avec un moteur d’image et précise le statut réel de la sortie.","sha256":"c4b14f8261dac700d1e2c72b855628a3c33f669b6d5dfaf77110c2be0d294361"}]$raccourcia$::jsonb) as x(
  ref text, moteur text, payload text, sha256 text
);

do $ctrl$
begin
  if (select count(*) from lot_v5_payloads) <> 30 then
    raise exception 'Lot 224 tronque : % lignes au lieu de 30.',
      (select count(*) from lot_v5_payloads);
  end if;
end $ctrl$;

-- 1. L'ancien courant sort du courant.
update public.prompt_versions pv
set is_current = false, status = 'retired'::public.version_status
from lot_v5_payloads l
join public.prompts p on p.external_ref = l.ref
join public.prompt_variants v on v.prompt_id = p.id
join public.ai_providers pr on pr.id = v.provider_id and pr.key = l.moteur
where pv.variant_id = v.id and pv.is_current and pv.payload is distinct from l.payload;

-- 2. Poser le nouveau texte la ou plus rien n'est courant.
insert into public.prompt_versions (variant_id, version_label, payload, status, is_current, published_at)
select v.id, 'v5-final', l.payload, 'published'::public.version_status, true, now()
from lot_v5_payloads l
join public.prompts p on p.external_ref = l.ref
join public.prompt_variants v on v.prompt_id = p.id
join public.ai_providers pr on pr.id = v.provider_id and pr.key = l.moteur
where not exists (
  select 1 from public.prompt_versions pv where pv.variant_id = v.id and pv.is_current
);

-- 3. Un texte identique deja archive redevient le courant : rejouer le lot ne
--    cree pas une version de plus.
update public.prompt_versions pv
set is_current = true, status = 'published'::public.version_status
from lot_v5_payloads l
join public.prompts p on p.external_ref = l.ref
join public.prompt_variants v on v.prompt_id = p.id
join public.ai_providers pr on pr.id = v.provider_id and pr.key = l.moteur
where pv.variant_id = v.id and pv.payload = l.payload and not pv.is_current
  and not exists (select 1 from public.prompt_versions a where a.variant_id = v.id and a.is_current);

do $ctrl$
declare
  v_pose integer;
begin
  select count(*) into v_pose
  from lot_v5_payloads l
  join public.prompts p on p.external_ref = l.ref
  join public.prompt_variants v on v.prompt_id = p.id
  join public.ai_providers pr on pr.id = v.provider_id and pr.key = l.moteur
  join public.prompt_versions pv on pv.variant_id = v.id and pv.is_current
  where pv.payload = l.payload;
  if v_pose <> 30 then
    raise exception 'Lot 224 : % payloads courants sur 30.', v_pose;
  end if;
end $ctrl$;

drop table lot_v5_payloads;
